import { useMutation, useQueryClient } from '@tanstack/react-query'
import { useState } from 'react'
import { generateBackupSSHKey, type BackupConfig } from '../../lib/api/backups'

const backupsQueryKey = ['backups'] as const

/**
 * The SSH key of the Manager for its SFTP repositories (decision D-13):
 * generated by an administrator, its public part installed on the servers.
 * wanted: an SFTP repository is chosen or stored.
 */
export function useBackupSSHKey(
  config: BackupConfig | undefined,
  canManage: boolean,
  wanted: boolean,
) {
  const queryClient = useQueryClient()
  const key = config?.sshKey ?? null
  const [confirmReplace, setConfirmReplace] = useState(false)
  const [copied, setCopied] = useState(false)
  const generate = useMutation({
    mutationFn: generateBackupSSHKey,
    onSuccess: (saved) => {
      setConfirmReplace(false)
      setCopied(false)
      queryClient.setQueryData([...backupsQueryKey, 'config'], saved)
    },
  })
  const clipboard = typeof navigator !== 'undefined' ? navigator.clipboard : undefined
  const sftpStored = config?.repository?.type === 'sftp' || config?.copy?.repository.type === 'sftp'

  return {
    visible: config !== undefined && (key !== null || wanted || sftpStored),
    canManage,
    key,
    secretsAvailable: config?.secretsAvailable ?? true,
    /** Generates the first key at once; replacing one asks first. */
    generate: () => (key ? setConfirmReplace(true) : generate.mutate()),
    confirmReplace,
    replace: () => generate.mutate(),
    cancelReplace: () => setConfirmReplace(false),
    isGenerating: generate.isPending,
    generateError: generate.error?.message ?? null,
    /** Copy needs a secure context (HTTPS or localhost); the key can be selected otherwise. */
    canCopy: key !== null && clipboard !== undefined,
    copied,
    copyPublicKey: () => {
      if (!key || !clipboard) return
      clipboard.writeText(key.publicKey).then(
        () => setCopied(true),
        () => setCopied(false),
      )
    },
  }
}

export type BackupSSHKeyModel = ReturnType<typeof useBackupSSHKey>
